package com.example.bandlink.entity; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="reports") public class Report { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) User reporter; @Enumerated(EnumType.STRING) @Column(nullable=false) ReportTargetType targetType; @Column(nullable=false) Long targetId; @Column(nullable=false,columnDefinition="text") String reasonText; @Enumerated(EnumType.STRING) @Column(nullable=false) ReportStatus status=ReportStatus.PENDING; @Column(nullable=false) LocalDateTime createdAt; protected Report(){} public Report(User r,ReportTargetType t,Long target,String reason,LocalDateTime now){reporter=r;targetType=t;targetId=target;reasonText=reason;createdAt=now;} public Long getId(){return id;} public ReportStatus getStatus(){return status;} }
